                iv_19_r = float(r_row.get("IVA 19%", 0.0) or 0.0)
                if iv_5_r <= 0 and iv_19_r <= 0 and iv_tot_r > 0:
                    df.at[idx_row, "IVA 19%"] = iv_tot_r
