                        if folio.endswith(".0"):
                            folio = folio[:-2]
                        prefijo = str(r.get("Prefijo", "")).strip() if pd.notna(r.get("Prefijo")) else ""
                        if prefijo == "nan" or prefijo == "None":
                            prefijo = ""
    
